name: Collect Wunstorf and ETNW observations

on:
  push:
    branches: [main]
    paths:
      - 'src/fetch_wunstorf.py'
      - 'src/fetch_etnw_metar.py'
      - 'src/audit_secondary_integrity.py'
      - 'src/push_private.py'
      - 'src/finalize_secondary_batch.py'
      - 'src/check_collection_due.py'
      - 'config/integrity_policy.json'
      - '.github/workflows/collect-secondary.yml'
  schedule:
    - cron: '47 0,4,10,16,22 * * *'
  workflow_dispatch:
    inputs:
      cloud_canary:
        description: "Bounded B2 transfer test on an isolated control branch"
        type: boolean
        default: false
      watchdog:
        description: 'Routine external watchdog trigger; respects freshness gate'
        type: boolean
        default: false

permissions:
  contents: read

concurrency:
  group: public-secondary-observations${{ inputs.cloud_canary == true && '-b2-canary' || '' }}
  cancel-in-progress: true

jobs:
  collect:
    if: github.repository == 'janwohlers78/mardorf-data-collector'
    runs-on: ubuntu-latest
    timeout-minutes: 6
    steps:
      - uses: actions/checkout@11d5960a326750d5838078e36cf38b85af677262
        with:
          persist-credentials: false

      - name: Check whether routine secondary collection is due
        id: due
        if: github.event_name == 'schedule' || (github.event_name == 'workflow_dispatch' && inputs.watchdog == true)
        env:
          PRIVATE_REPO_TOKEN: ${{ secrets.PRIVATE_REPO_TOKEN }}
          PRIVATE_REPO: janwohlers78/mardorf-kitevorhersage
        run: PYTHONPATH=src python3 -m mardorf_collector check-collection-due --kind secondary --max-age-minutes 240

      - name: Report skipped routine secondary trigger
        if: (github.event_name == 'schedule' || (github.event_name == 'workflow_dispatch' && inputs.watchdog == true)) && steps.due.outputs.due != 'true'
        run: |
          {
            echo "## Secondary collector freshness gate"
            echo
            echo "- Provider fetch skipped: latest verified secondary batch is still within the target interval."
            echo "- Previous batch: ${{ steps.due.outputs.last_success_generated_at_utc }}"
            echo "- Age: ${{ steps.due.outputs.age_minutes }} min"
            echo "- Threshold: ${{ steps.due.outputs.threshold_minutes }} min"
            echo "- Reason: ${{ steps.due.outputs.reason }}"
          } >> "$GITHUB_STEP_SUMMARY"

      - name: Verify canonical storage before provider acquisition
        id: storage_gate
        if: (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        env:
          PRIVATE_REPO_TOKEN: ${{ secrets.PRIVATE_REPO_TOKEN }}
          B2_APPLICATION_KEY_ID: ${{ secrets.B2_APPLICATION_KEY_ID }}
          B2_APPLICATION_KEY: ${{ secrets.B2_APPLICATION_KEY }}
          B2_ENDPOINT_URL: ${{ vars.B2_ENDPOINT_URL }}
          B2_REGION: ${{ vars.B2_REGION }}
          B2_BUCKET: ${{ vars.B2_BUCKET }}
          CLOUD_CANARY: ${{ inputs.cloud_canary == true && 'true' || 'false' }}
        run: |
          python3 -m pip install --disable-pip-version-check --require-hashes --only-binary=:all: -r requirements-runtime.txt -r requirements-cloud.txt
          PYTHONPATH=src python3 -m mardorf_collector.runtime.storage_preflight

      - uses: actions/setup-python@a26af69be951a213d495a4c3e4e4022e16d87065
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        with:
          python-version: '3.12'

      - name: Install pinned runtime dependencies
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        run: |
          python -m pip install --disable-pip-version-check --require-hashes --only-binary=:all: -r requirements-runtime.txt
          if [ "${{ inputs.cloud_canary }}" = "true" ] || python -c "import json,sys; sys.exit(0 if json.load(open('config/dev03_cloud_runtime_v1.json'))['production_enabled'] is True else 1)"; then
            python -m pip install --disable-pip-version-check --require-hashes --only-binary=:all: -r requirements-cloud.txt
          fi

      - name: Fetch DWD Wunstorf historical reference
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        continue-on-error: true
        run: PYTHONPATH=src python -m mardorf_collector fetch-wunstorf

      - name: Audit Wunstorf
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        run: PYTHONPATH=src python -m mardorf_collector audit-secondary-integrity --kind wunstorf --input work/wunstorf_bundle.json --json-out work/wunstorf_integrity.json --md-out work/wunstorf_integrity.md

      - name: Fetch ETNW METAR redundancy
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        continue-on-error: true
        run: PYTHONPATH=src python -m mardorf_collector fetch-etnw-metar

      - name: Audit ETNW
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        run: PYTHONPATH=src python -m mardorf_collector audit-secondary-integrity --kind etnw --input work/etnw_bundle.json --json-out work/etnw_integrity.json --md-out work/etnw_integrity.md

      - name: Transfer Wunstorf payload and integrity
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        env:
          PRIVATE_REPO_TOKEN: ${{ secrets.PRIVATE_REPO_TOKEN }}
          PRIVATE_REPO: janwohlers78/mardorf-kitevorhersage
          B2_APPLICATION_KEY_ID: ${{ secrets.B2_APPLICATION_KEY_ID }}
          B2_APPLICATION_KEY: ${{ secrets.B2_APPLICATION_KEY }}
          B2_ENDPOINT_URL: ${{ vars.B2_ENDPOINT_URL }}
          B2_REGION: ${{ vars.B2_REGION }}
          B2_BUCKET: ${{ vars.B2_BUCKET }}
        run: PYTHONPATH=src python -m mardorf_collector.transfer.dispatch publish --cloud-canary "${{ inputs.cloud_canary == true && 'true' || 'false' }}" --kind wunstorf --file work/wunstorf_bundle.json --integrity-json work/wunstorf_integrity.json --integrity-md work/wunstorf_integrity.md

      - name: Transfer ETNW payload and integrity
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        env:
          PRIVATE_REPO_TOKEN: ${{ secrets.PRIVATE_REPO_TOKEN }}
          PRIVATE_REPO: janwohlers78/mardorf-kitevorhersage
          B2_APPLICATION_KEY_ID: ${{ secrets.B2_APPLICATION_KEY_ID }}
          B2_APPLICATION_KEY: ${{ secrets.B2_APPLICATION_KEY }}
          B2_ENDPOINT_URL: ${{ vars.B2_ENDPOINT_URL }}
          B2_REGION: ${{ vars.B2_REGION }}
          B2_BUCKET: ${{ vars.B2_BUCKET }}
        run: PYTHONPATH=src python -m mardorf_collector.transfer.dispatch publish --cloud-canary "${{ inputs.cloud_canary == true && 'true' || 'false' }}" --kind etnw --file work/etnw_bundle.json --integrity-json work/etnw_integrity.json --integrity-md work/etnw_integrity.md

      - name: Gate Wunstorf integrity
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        run: python -c "import json; d=json.load(open('work/wunstorf_integrity.json')); assert d['error_count']==0, d"

      - name: Gate ETNW integrity
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        run: python -c "import json; d=json.load(open('work/etnw_integrity.json')); assert d['error_count']==0, d"

      - name: Finalize atomic secondary batch receipt
        if: steps.storage_gate.outcome == 'success' && (github.event_name == 'push' || (github.event_name == 'workflow_dispatch' && inputs.watchdog != true) || steps.due.outputs.due == 'true')
        env:
          PRIVATE_REPO_TOKEN: ${{ secrets.PRIVATE_REPO_TOKEN }}
          PRIVATE_REPO: janwohlers78/mardorf-kitevorhersage
          B2_APPLICATION_KEY_ID: ${{ secrets.B2_APPLICATION_KEY_ID }}
          B2_APPLICATION_KEY: ${{ secrets.B2_APPLICATION_KEY }}
          B2_ENDPOINT_URL: ${{ vars.B2_ENDPOINT_URL }}
          B2_REGION: ${{ vars.B2_REGION }}
          B2_BUCKET: ${{ vars.B2_BUCKET }}
        run: |
          PYTHONPATH=src python -m mardorf_collector.transfer.dispatch secondary --cloud-canary "${{ inputs.cloud_canary == true && 'true' || 'false' }}" \
            --wunstorf-integrity work/wunstorf_integrity.json \
            --etnw-integrity work/etnw_integrity.json

